        const response: Cart = { cartId: 'C1', items: [], totalPrice: 0 };

        service.addItem('C1', 'P1', 'L1', 1).subscribe();

        const req = httpMock.expectOne('/api/cart/items');
        expect(req.request.headers.get('X-Cart-Id')).toBe('C1');
        req.flush(response);
      });
    });
