        builder.HasKey(x => new { x.ProductId, x.SupplierId });
        builder.Property(x => x.Price).HasPrecision(18, 2);

        builder.HasOne(x => x.Supplier)
            .WithMany(x => x.Offers)
            .HasForeignKey(x => x.SupplierId);
    }
}

